#include "cJSON.h"
#include "lodepng.h"

#include <algorithm>
#include <cstdlib>
#include <fstream>
#include <iostream>
#include <sstream>
#include <string>
#include <vector>

namespace {

struct Layer {
    int rows = 0;
    int cols = 0;
    std::vector<float> weights;
    std::vector<float> bias;
};

[[noreturn]] void fail(const std::string& message) {
    std::cerr << "cli_tool: " << message << '\n';
    std::exit(1);
}

std::string read_text_file(const char* path) {
    std::ifstream input(path, std::ios::binary);
    if (!input) fail(std::string("cannot open ") + path);
    std::ostringstream contents;
    contents << input.rdbuf();
    if (!input.good() && !input.eof()) fail(std::string("cannot read ") + path);
    return contents.str();
}

const cJSON* object_item(const cJSON* object, const char* name) {
    const cJSON* item = cJSON_GetObjectItemCaseSensitive(object, name);
    if (!item) fail(std::string("weights.json is missing ") + name);
    return item;
}

int integer_value(const cJSON* item, const char* description) {
    if (!cJSON_IsNumber(item) || item->valuedouble != static_cast<int>(item->valuedouble)) {
        fail(std::string("invalid ") + description);
    }
    return static_cast<int>(item->valuedouble);
}

Layer read_layer(const cJSON* layers, const char* name, int expected_rows, int expected_cols) {
    const cJSON* layer = object_item(layers, name);
    if (!cJSON_IsObject(layer)) fail(std::string("layer ") + name + " is not an object");

    const cJSON* shape = object_item(layer, "weight_shape");
    if (!cJSON_IsArray(shape) || cJSON_GetArraySize(shape) != 2) {
        fail(std::string("invalid shape for ") + name);
    }
    const int rows = integer_value(cJSON_GetArrayItem(shape, 0), "layer row count");
    const int cols = integer_value(cJSON_GetArrayItem(shape, 1), "layer column count");
    if (rows != expected_rows || cols != expected_cols) {
        fail(std::string("unexpected shape for ") + name);
    }

    const cJSON* weight = object_item(layer, "weight");
    if (!cJSON_IsArray(weight) || cJSON_GetArraySize(weight) != rows) {
        fail(std::string("invalid weights for ") + name);
    }
    Layer result;
    result.rows = rows;
    result.cols = cols;
    result.weights.reserve(static_cast<size_t>(rows) * cols);
    for (int row = 0; row < rows; ++row) {
